import {svgColor} from './svg.mjs';
const $=id=>document.getElementById(id),frame=$('preview');let selection=null;
addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==new URL(frame.src).origin)return;const m=e.data;
 if(m?.type==='dragger:selection'){selection=m.selection;$('svg-colors').hidden=m.tag!=='img';$('svg-controls').replaceChildren();$('svg-status').textContent=m.tag==='img'?'로고의 색상을 읽는 중…':'화면에서 로고 이미지를 직접 클릭하면 색상을 바꿀 수 있습니다.';if(m.tag==='img')frame.contentWindow.postMessage({type:'dragger:svg-inspect',selection},e.origin);}
 if(m?.type==='dragger:svg-selection'&&m.selection===selection){$('svg-status').textContent=m.message;$('svg-controls').replaceChildren();for(const slot of m.slots||[]){const row=document.createElement('div');row.className='color-row';const label=document.createElement('label');label.textContent=slot.label;const picker=document.createElement('input');picker.type='color';picker.setAttribute('aria-label',slot.label+' 선택');const input=document.createElement('input');input.type='text';input.setAttribute('aria-label',slot.label+' 색상값');input.value=slot.value;const normalize=v=>v.length===4?'#'+[...v.slice(1)].map(c=>c+c).join(''):v.slice(0,7);picker.value=normalize(slot.value);const apply=value=>{input.value=value;if(!svgColor(value)){input.setCustomValidity('HEX 색상값을 입력하세요.');return;}input.setCustomValidity('');picker.value=normalize(value);frame.contentWindow.postMessage({type:'dragger:svg-style',selection,slot:slot.key,value},e.origin);};picker.oninput=()=>apply(picker.value);input.onchange=()=>apply(input.value.trim());label.append(picker);row.append(label,input);$('svg-controls').append(row);}}
});
